from weekdate import week_bounds, week_of


def test_jan1_is_in_week1():
    assert week_of("2021-01-01") == (2021, 1)


def test_week1_contains_jan1():
    assert week_bounds(2021, 1) == ("2020-12-28", "2021-01-03")


def test_dates_stay_in_calendar_year():
    assert week_of("2019-12-30") == (2019, 53)
